package in.ac.rtu.medicare.network;
import java.io.*; import java.net.*; import java.time.*; import java.util.concurrent.*;
/** Line-based socket server for demonstrable appointment notifications. Run independently, never from a servlet thread. */
public final class NotificationServer { public static void main(String[] args)throws IOException {int port=args.length>0?Integer.parseInt(args[0]):5050;try(ServerSocket server=new ServerSocket(port);ExecutorService pool=Executors.newVirtualThreadPerTaskExecutor()){System.out.println("MediCare notification server on "+port);while(true){Socket s=server.accept();pool.submit(()->handle(s));}}}private static void handle(Socket s){try(s;BufferedReader in=new BufferedReader(new InputStreamReader(s.getInputStream()));PrintWriter out=new PrintWriter(s.getOutputStream(),true)){String message=in.readLine();if(message==null||message.length()>500)throw new IOException("Invalid message");out.println("ACK "+Instant.now()+" "+message);}catch(IOException ignored){}} }
